flowchart TB
    S["Decision point"] --> Q1{"Can code or rules decide it?"}
    Q1 -->|"yes"| R0["Rung 0: code"]
    Q1 -->|"no"| Q2{"Is one model output enough?"}
    Q2 -->|"yes"| R1["Rung 1: single call, checked"]
    Q2 -->|"no"| Q3{"Can the steps be written in advance?"}
    Q3 -->|"yes"| R2["Rung 2: workflow with model steps"]
    Q3 -->|"no"| Q4{"Cheap independent check before the effect?"}
    Q4 -->|"no"| D["Rung 3 that drafts only; a human or rule decides"]
    Q4 -->|"yes"| Q5{"Short horizon, budget fits?"}
    Q5 -->|"yes"| R3["Rung 3: bounded loop"]
    Q5 -->|"no"| R4["Rung 4: autonomous, in an envelope"]

flowchart TB
    Q1{"Does it change anything outside the run?"} -->|"no"| R["Read: size cost and data exposure"]
    Q1 -->|"yes"| Q2{"Does a human act on it before it takes effect?"}
    Q2 -->|"yes"| D["Draft in a staging store"]
    Q2 -->|"no"| Q3{"Does it bind the organization to a third party?"}
    Q3 -->|"yes"| X["External commitment"]
    Q3 -->|"no"| Q4{"Can the system restore it exactly, alone, inside a known window?"}
    Q4 -->|"yes"| W["Reversible write"]
    Q4 -->|"no"| Q5{"Can a forward action offset it?"}
    Q5 -->|"yes"| C["Compensable write"]
    Q5 -->|"no"| I["Irreversible write"]

flowchart TB
    Q["What will the result be used for?"] --> A{"Does it drive an action or a commitment?"}
    A -->|"yes"| L["Typed lookup on the owning API, re-read before commit"]
    A -->|"no"| B{"Is it a defined business metric or entity?"}
    B -->|"yes"| M["Semantic layer or governed view, row policy for the principal"]
    B -->|"no"| C{"Will a person read the result before it is used?"}
    C -->|"yes"| F["Free SQL in an analyst copilot, read-only, row limits"]
    C -->|"no"| X["Do not give the agent this read; ask the data owner for a view"]

flowchart TB
    Q["What does the claim need?"] --> SOR{"Is there a system of record for this fact?"}
    SOR -->|"yes"| LOOK["Structured lookup tool"]
    SOR -->|"no"| SIZE{"Is the corpus small, versioned and mostly relevant?"}
    SIZE -->|"yes"| LOAD["Load whole corpus, cached"]
    SIZE -->|"no"| NAV{"Is the source navigable with exact identifiers, like code?"}
    NAV -->|"yes"| AGS["Agentic search"]
    NAV -->|"no"| TOOL["Retrieval tool over a hybrid index"]

flowchart TB
    A["Session type"] --> B{"Untrusted text in context?"}
    B -->|"no"| OK["Two legs or fewer: standard review"]
    B -->|"yes"| C{"Private data readable?"}
    C -->|"no"| OK
    C -->|"yes"| D{"Any outbound channel, incl. search, fetch, render, delegation?"}
    D -->|"no"| OK
    D -->|"yes"| E{"Data and sink scoped to the same principal?"}
    E -->|"yes"| F["Scoped trifecta: enforce scope, sign residual"]
    E -->|"no"| G["Full trifecta: split the session, remove a leg or add a human"]

